css:
/* A published <theme-id>.jpg supplies the lake. The fallback keeps imported copies readable. */
:root {
  --aurora-backdrop: var(--theme-background-image, linear-gradient(155deg, #21384a 4%, #3d5b54 22%, #29384b 38%, #141720 60%, #213447 83%, #10151d));
  --aurora-glass: linear-gradient(rgb(14 22 19 / 2%), rgb(14 22 19 / 2%));
  /* With the 2% tint and 92% window opacity this matches Ghostty's 0.4316 lake ink. */
  --aurora-pane: linear-gradient(rgb(10 16 13 / 46%), rgb(10 16 13 / 46%));
  /* Darken caps each wallpaper channel, so tiled windows keep the aurora core no brighter than Ghostty. */
  --aurora-crest: linear-gradient(#365a58, #365a58);
}
[data-slot="sidebar-inner"], [data-slot="sidebar"][data-mobile], [data-chat-header], [data-workspace-area="conversation"], [data-workspace-area="panel"]:has(.\@container\/pr-header) {
  isolation: isolate;
  background: var(--aurora-crest), var(--app-theme-canvas) var(--aurora-backdrop) center / cover fixed no-repeat;
  background-blend-mode: darken, normal;
  paint-order: stroke fill;
  -webkit-text-stroke: 1px rgb(10 16 13 / 55%);
  text-shadow: 0 0 1.2px rgb(10 16 13 / 55%);
}
[data-slot="sidebar-inner"] { position: relative; }
[data-chat-header] { border-bottom: 1px solid var(--app-theme-toolbar-border); }
[data-slot="sidebar-inner"]::before, [data-slot="sidebar"][data-mobile]::before, [data-chat-header]::before, [data-workspace-area="conversation"]::before, [data-workspace-area="panel"]:has(.\@container\/pr-header)::before {
  content: "";
  position: absolute;
  inset: 0;
  z-index: -1;
  border-radius: inherit;
  pointer-events: none;
  backdrop-filter: blur(24px);
  background: var(--aurora-pane), var(--aurora-glass);
}
[data-thread-item] [aria-current="page"] {
  background: rgb(133 217 172 / 20%);
  box-shadow: inset 3px 0 var(--app-theme-accent);
}
[data-thread-details-card] { background-color: rgb(10 16 13 / 34%); }
/* An empty timeline (new thread) gets an opaque bg-background placeholder. Let the pane lake show. */
[data-workspace-area="conversation"] [data-timeline-loading] { background: transparent !important; }
/* T3 backs the turn diff card header with opaque bg-background. Keep both layers glass. */
[data-changed-files-state] { background: rgb(10 16 13 / 34%) !important; }
[data-changed-files-state] > [data-changed-files-header] {
  background: rgb(10 16 13 / 30%) !important;
  -webkit-backdrop-filter: blur(24px);
  backdrop-filter: blur(24px);
}
/* T3 opens Usage and Settings in one AppRouteModal filled with opaque bg-background. Keep it lake glass; alerts and other dialogs keep their own fills. */
.dialog-backdrop:has(~ * [data-app-modal]) { background: rgb(10 16 13 / 24%) !important; }
[data-app-modal] {
  background: rgb(10 16 13 / 44%) !important;
  -webkit-backdrop-filter: blur(24px);
  backdrop-filter: blur(24px);
}
/* Settings repeats opaque sidebar and card fills there. Its nav overlays content on narrow windows and diagnostics headers stick over rows, so both blur. */
[data-app-modal] nav.bg-sidebar, [data-app-modal] .bg-card {
  background: rgb(10 16 13 / 34%) !important;
  -webkit-backdrop-filter: blur(24px);
  backdrop-filter: blur(24px);
}
[data-user-message-bubble] {
  background: rgb(0 0 0 / 45%);
  border: 1px solid var(--app-theme-border) !important;
}
.chat-markdown a[href^="https://"], .chat-markdown a[href^="http://"] {
  color: var(--app-theme-accent) !important;
  text-decoration: underline;
}
/* T3 fills the PR detail panel with opaque bg-background. Share the pane lake there; glass only its named canvas fills, so outline controls and label chips keep their own. */
.bg-background:has(> .\@container\/pr-header) { background: transparent !important; }
.bg-background:has(> .\@container\/pr-header) .sticky.bg-background {
  background: rgb(10 16 13 / 30%) !important;
  -webkit-backdrop-filter: blur(24px);
  backdrop-filter: blur(24px);
}
.bg-background:has(> .\@container\/pr-header) article.bg-background, .bg-background:has(> .\@container\/pr-header) .rounded-xl.bg-background, .bg-background:has(> .\@container\/pr-header) .\@container.bg-background { background: rgb(10 16 13 / 34%) !important; }
/* Timeline badges mask the rail; a clear blur keeps that mask without a canvas tile. */
.bg-background:has(> .\@container\/pr-header) .size-8.bg-background, .bg-background:has(> .\@container\/pr-header) .size-7.bg-background {
  background: transparent !important;
  -webkit-backdrop-filter: blur(24px);
  backdrop-filter: blur(24px);
}
/* Fenced code blocks get the opaque --code-background. Black glass keeps pierre-dark syntax contrast over the lake. */
.chat-markdown .chat-markdown-codeblock { background-color: rgb(0 0 0 / 55%) !important; }
.chat-markdown :not(pre) > code { background-color: rgb(0 0 0 / 28%); }
[data-slot="composer-shell"] { --chat-composer-glass-surface: transparent !important; }
[data-slot="composer-host"] {
  background: rgb(10 16 13 / 52%) !important;
  border: 1px solid var(--app-theme-border) !important;
}
/* T3 paints .surface-glass with 80% of the opaque canvas; keep the lake continuous. */
[data-slot="composer-context-strip"] {
  background: transparent !important;
  -webkit-backdrop-filter: none !important;
  backdrop-filter: none !important;
  text-shadow: 0 0 2px rgb(10 16 13 / 70%);
}
html[data-theme-id] .surface-glass { background: rgb(10 16 13 / 48%); }
[data-slot="composer-host"]:focus-within {
  border-color: var(--app-theme-focus) !important;
  box-shadow: inset 0 0 0 1px var(--app-theme-focus) !important;
}
::selection { color: var(--app-theme-accent-foreground); background: var(--app-theme-accent); }
